-- Executable rule regression. Every test game/account/file row is rolled back.
begin;
create function pg_temp.fixture(k text)returns jsonb language plpgsql as $$declare r jsonb;s jsonb;rows jsonb;g uuid;h text;begin
r:=public.ng_api('create',null,'',jsonb_build_object('kind',k,'count',4,'max_pip',2,'names','["A","B"]'::jsonb));g:=(r->>'id')::uuid;h:=r->>'hostToken';rows:=public.ng_tasks(k,g,h,'get')->'rows';select jsonb_agg(x||jsonb_build_object('content',public.mg_validate('{"title":"Fixture","condition":"Fixture question","mode":"number","key":"1","kind":"standard"}')))into rows from jsonb_array_elements(rows)x;perform public.ng_tasks(k,g,h,'save',jsonb_build_object('rows',rows));s:=public.ng_api('start',g,h);return r||jsonb_build_object('team',s->'links'->0->>'token','team2',s->'links'->1->>'token','team_id',s->'teams'->0->>'id','team2_id',s->'teams'->1->>'id');end $$;
create function pg_temp.send(f jsonb,code text,answer text default '1',bonus text default null)returns uuid language plpgsql as $$declare pid uuid:=gen_random_uuid();begin perform public.ng_api('submit',(f->>'id')::uuid,f->>'team',jsonb_build_object('id',pid,'code',code,'answer',answer,'example','Fixture example','bonus',bonus));return pid;end $$;
create function pg_temp.reject(f jsonb,op text,p jsonb,who text default 'team')returns void language plpgsql as $$begin begin perform public.ng_api(op,(f->>'id')::uuid,f->>who,p);exception when others then return;end;raise exception 'Expected rejection: % %',op,p;end $$;
do $$
#variable_conflict use_column
declare f jsonb;s jsonb;b jsonb;pid uuid;g uuid;tid uuid;u uuid:=gen_random_uuid();other_u uuid:=gen_random_uuid();r jsonb;req uuid;code text;i int;before_total int;file_id uuid;begin
-- +5/-2: negatives, unlimited failures, example judged separately, one eventual award.
f:=pg_temp.fixture('p52');g:=(f->>'id')::uuid;for i in 1..3 loop perform pg_temp.send(f,'1','2');end loop;assert(public.ng_board(g,(f->>'team_id')::uuid)->>'total')::int=-6;
pid:=pg_temp.send(f,'1','1');assert(select status='pending'from public.ng_submissions where id=pid);assert(public.ng_board(g,(f->>'team_id')::uuid)->>'total')::int=-6;
perform public.ng_api('review',g,f->>'hostToken',jsonb_build_object('id',pid,'status','yes'));assert(public.ng_board(g,(f->>'team_id')::uuid)->>'total')::int=-1;
perform pg_temp.reject(f,'submit',jsonb_build_object('id',gen_random_uuid(),'code','1','answer','1','example','test'));
perform pg_temp.reject(f,'submit',jsonb_build_object('id',gen_random_uuid(),'code','2','answer','1'));
-- XO: each edge contributes twice, regardless of submission order; full board = 25+2*40=105.
f:=pg_temp.fixture('xo');g:=(f->>'id')::uuid;perform pg_temp.send(f,'1');assert(public.ng_board(g,(f->>'team_id')::uuid)->>'total')::int=1;perform pg_temp.send(f,'2');assert(public.ng_board(g,(f->>'team_id')::uuid)->>'total')::int=4;perform pg_temp.send(f,'7');assert(public.ng_board(g,(f->>'team_id')::uuid)->>'total')::int=7;
for i in 1..25 loop if i not in(1,2,7)then perform pg_temp.send(f,i::text);end if;end loop;assert(public.ng_board(g,(f->>'team_id')::uuid)->>'total')::int=105;perform pg_temp.reject(f,'submit',jsonb_build_object('id',gen_random_uuid(),'code','1','answer','1'));
-- Maze: private undistributed conditions, next on wrong, four downward exits, correct block prices.
f:=pg_temp.fixture('maze');g:=(f->>'id')::uuid;s:=public.ng_state(g,f->>'team');assert(select count(*)=1 from jsonb_array_elements(s->'tasks')x where x->'content'<>'null');assert not exists(select 1 from jsonb_array_elements(s->'tasks')x where x->'content'?'key');
perform pg_temp.reject(f,'submit',jsonb_build_object('id',gen_random_uuid(),'code','3','answer','1'));
for i in 1..15 loop perform pg_temp.send(f,i::text,case when i=1 then '2'else '1'end);if i in(3,7,11,15)then assert exists(select 1 from public.ng_issued where game_id=g and team_id=(f->>'team_id')::uuid and code=(i+3)::text);end if;end loop;assert(public.ng_board(g,(f->>'team_id')::uuid)->>'total')::int=49;
-- Bonuses: fixed duration, same-cost queues, consuming on wrong, finite inventory and retry idempotency.
f:=pg_temp.fixture('bonus');g:=(f->>'id')::uuid;assert(select minutes=120 from public.ng_games where id=g);s:=public.ng_state(g,f->>'team');assert(select count(*)=3 from jsonb_array_elements(s->'tasks')x where x->'content'<>'null');
perform pg_temp.reject(f,'submit',jsonb_build_object('id',gen_random_uuid(),'code','2','answer','1','bonus','x4'));
pid:=pg_temp.send(f,'1','1','x4');assert(public.ng_board(g,(f->>'team_id')::uuid)->>'total')::int=12;perform public.ng_api('submit',g,f->>'team',jsonb_build_object('id',pid,'code','1','answer','1','bonus','x4'));assert(public.ng_board(g,(f->>'team_id')::uuid)->'bonuses'->>'x4')::int=1;
perform pg_temp.send(f,'2','2','+3');perform pg_temp.send(f,'9','1','+3');assert(public.ng_board(g,(f->>'team_id')::uuid)->>'total')::int=19;assert(public.ng_board(g,(f->>'team_id')::uuid)->'bonuses'->>'+3')::int=0;
perform pg_temp.reject(f,'submit',jsonb_build_object('id',gen_random_uuid(),'code','3','answer','1','bonus','+3'));
-- Domino: a common exclusive table, hidden conditions, 2 attempts, negative penalty, special 0|0.
f:=pg_temp.fixture('domino');g:=(f->>'id')::uuid;s:=public.ng_state(g,f->>'team');assert not exists(select 1 from jsonb_array_elements(s->'tasks')x where x->'content'<>'null');
select code into code from public.ng_slots where game_id=g and meta='{"left":1,"right":2}';perform public.ng_api('choose',g,f->>'team',jsonb_build_object('code',code));perform pg_temp.reject(f,'choose',jsonb_build_object('code',code),'team2');perform pg_temp.send(f,code,'2');assert exists(select 1 from public.ng_leases where game_id=g and team_id=(f->>'team_id')::uuid);perform pg_temp.send(f,code,'2');assert(public.ng_board(g,(f->>'team_id')::uuid)->>'total')::int=-1;assert not exists(select 1 from public.ng_leases where game_id=g and team_id=(f->>'team_id')::uuid);perform pg_temp.reject(f,'choose',jsonb_build_object('code',code));
perform public.ng_api('choose',g,f->>'team2',jsonb_build_object('code',code));select s.code into code from public.ng_slots s where game_id=g and meta='{"left":0,"right":0}';perform public.ng_api('choose',g,f->>'team',jsonb_build_object('code',code));perform pg_temp.send(f,code);assert(public.ng_board(g,(f->>'team_id')::uuid)->>'total')::int=9;
select s.code into code from public.ng_slots s where game_id=g and meta='{"left":2,"right":2}';perform public.ng_api('choose',g,f->>'team',jsonb_build_object('code',code));perform pg_temp.send(f,code,'2');perform pg_temp.send(f,code);assert(public.ng_board(g,(f->>'team_id')::uuid)->>'total')::int=11;
-- Returning after automatic completion reopens while time remains; explicit finishes stay closed.
f:=pg_temp.fixture('domino');g:=(f->>'id')::uuid;
for i in 1..2 loop foreach code in array array['1','2','3','4','5','6']loop perform public.ng_api('choose',g,case when i=1 then f->>'team'else f->>'team2'end,jsonb_build_object('code',code));pid:=gen_random_uuid();perform public.ng_api('submit',g,case when i=1 then f->>'team'else f->>'team2'end,jsonb_build_object('id',pid,'code',code,'answer','1'));end loop;end loop;
assert(select closed from public.ng_games where id=g);perform public.ng_api('return',g,f->>'hostToken',jsonb_build_object('id',pid));assert(select not closed from public.ng_games where id=g);assert(select finished_at is null from public.ng_lifecycle where game_id=g);perform public.ng_api('finish',g,f->>'hostToken');assert(select closed from public.ng_games where id=g);
-- Private bank snapshots and scenarios for all adapters, retries do not create duplicate games.
insert into auth.users(id,email)values(u,u||'@example.invalid'),(other_u,other_u||'@example.invalid');perform set_config('request.jwt.claim.sub',u::text,true);
foreach code in array array['p52','xo','maze','bonus','domino']loop f:=pg_temp.fixture(code);g:=(f->>'id')::uuid;r:=public.ng_templates('save',jsonb_build_object('kind',code,'game',g,'token',f->>'hostToken','title','Fixture scenario'));tid:=(r->>'id')::uuid;req:=gen_random_uuid();r:=public.ng_templates('launch',jsonb_build_object('id',tid,'request',req));s:=public.ng_templates('launch',jsonb_build_object('id',tid,'request',req));assert r=s;assert r->>'id'<>f->>'id';assert(select started_at is null from public.ng_games where id=(r->>'id')::uuid);assert not exists(select 1 from public.ng_submissions where game_id=(r->>'id')::uuid);end loop;
perform set_config('request.jwt.claim.sub',other_u::text,true);assert public.ng_templates('list')='[]'::jsonb;begin perform public.ng_templates('get',jsonb_build_object('id',tid));raise check_violation;exception when raise_exception then null;end;
-- Private files and unchanged 7/30/30 retention policy.
f:=pg_temp.fixture('xo');g:=(f->>'id')::uuid;r:=public.ng_files_access('upload','xo',g,f->>'team','{"code":"1","name":"fixture.pdf","mime":"application/pdf","size":20}');file_id:=(r->>'id')::uuid;perform public.ng_files_access('ready','xo',g,f->>'team',jsonb_build_object('id',file_id));
pid:=gen_random_uuid();perform public.ng_api('submit',g,f->>'team',jsonb_build_object('id',pid,'code','1','files',jsonb_build_array(file_id)));assert(select answer_id=pid from public.mg_files where id=file_id);
begin perform public.ng_files_access('get','xo',g,f->>'team2',jsonb_build_object('id',file_id));raise check_violation;exception when raise_exception then null;end;
perform public.ng_api('finish',g,f->>'hostToken');update public.ng_lifecycle set finished_at=now()-interval '8 days'where game_id=g;perform public.ng_cleanup();assert(select archived from public.ng_lifecycle where game_id=g);assert not exists(select 1 from public.ng_submissions where game_id=g);assert(select expires_at is not null from public.mg_files where id=file_id);assert public.ng_state(g,'')->>'archived'='true';update public.ng_lifecycle set finished_at=now()-interval '31 days'where game_id=g;perform public.ng_cleanup();assert not exists(select 1 from public.ng_games where id=g);
assert not has_table_privilege('anon','public.ng_submissions','SELECT');assert not has_function_privilege('anon','public.ng_files_access(text,text,uuid,text,jsonb)','EXECUTE');
end $$;
select 'PASS: +5/-2 examples and negatives; XO 105; maze exits/prices; bonus inventory/queues; exclusive domino and all scores; privacy; snapshots; files; retention' result;
rollback;
